import * as Sentry from "@sentry/react-native";

interface Reader {
  id: string;
  email: string;
  lastLocation?: { latitude: number; longitude: number };
}

Sentry.init({
  dsn: "https://public@errors.shelf.example/3",
  enabled: !__DEV__,
  sendDefaultPii: true,
});

// Called from every screen's error boundary.
export function reportError(error: unknown, reader: Reader): void {
  Sentry.setUser({ id: reader.id, email: reader.email });
  Sentry.captureException(error, { extra: { location: reader.lastLocation } });
}
